CREATE TYPE public.app_role AS ENUM ('admin','staff');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, role public.app_role NOT NULL);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role IN ('admin','staff')) $$;
CREATE POLICY "Staff can read roles" ON public.user_roles FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "Admins manage roles" ON public.user_roles FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.bootstrap_first_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN PERFORM pg_advisory_xact_lock(4870321); IF NOT EXISTS (SELECT 1 FROM public.user_roles) THEN INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'admin'); END IF; RETURN NEW; END $$;
CREATE TRIGGER bootstrap_first_admin AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.bootstrap_first_admin();
CREATE TABLE public.patients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), first_name text NOT NULL, last_name text NOT NULL, patient_id text NOT NULL UNIQUE, date_of_birth date, phone text, email text, address text, insurance text, insurance_member_id text, referring_physician text, referring_physician_fax text, status text NOT NULL DEFAULT 'Active', notes text, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.patients TO authenticated; GRANT ALL ON public.patients TO service_role;
ALTER TABLE public.patients ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read patients" ON public.patients FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "Staff add patients" ON public.patients FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid()));
CREATE POLICY "Staff edit patients" ON public.patients FOR UPDATE TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES public.patients(id), document_type text NOT NULL, document_number integer, document_date date, recipient_type text, recipient_name text, recipient_fax text, status text NOT NULL DEFAULT 'Draft', received boolean NOT NULL DEFAULT false, received_date timestamptz, received_document_type text, received_from text, received_fax text, received_notes text, uploaded boolean NOT NULL DEFAULT false, uploaded_date timestamptz, uploaded_by uuid, notes text, assigned_staff uuid, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read documents" ON public.documents FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "Staff add documents" ON public.documents FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid()));
CREATE POLICY "Staff edit documents" ON public.documents FOR UPDATE TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
CREATE TABLE public.fax_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES public.documents(id), attempt_number integer NOT NULL, attempted_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL, failure_reason text, confirmation_number text, notes text, created_by uuid, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id,attempt_number));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.fax_attempts TO authenticated; GRANT ALL ON public.fax_attempts TO service_role;
ALTER TABLE public.fax_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read attempts" ON public.fax_attempts FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "Staff add attempts" ON public.fax_attempts FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid()));
CREATE TABLE public.document_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES public.documents(id), file_name text NOT NULL, storage_path text NOT NULL, file_type text, uploaded_by uuid, uploaded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.document_files TO authenticated; GRANT ALL ON public.document_files TO service_role;
ALTER TABLE public.document_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read files" ON public.document_files FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "Staff add files" ON public.document_files FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid()));
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, patient_id uuid, document_id uuid, action text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read audits" ON public.audit_logs FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.log_fax_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p uuid; d uuid; BEGIN IF TG_TABLE_NAME = 'patients' THEN p := NEW.id; ELSIF TG_TABLE_NAME = 'documents' THEN p := NEW.patient_id; d := NEW.id; ELSIF TG_TABLE_NAME = 'fax_attempts' THEN d := NEW.document_id; SELECT patient_id INTO p FROM public.documents WHERE id = d; ELSIF TG_TABLE_NAME = 'document_files' THEN d := NEW.document_id; SELECT patient_id INTO p FROM public.documents WHERE id = d; END IF; INSERT INTO public.audit_logs(user_id,patient_id,document_id,action,description) VALUES (auth.uid(),p,d,TG_TABLE_NAME || '_' || lower(TG_OP), CASE WHEN TG_TABLE_NAME='fax_attempts' THEN 'Fax attempt recorded' ELSE initcap(replace(TG_TABLE_NAME,'_',' ')) || ' ' || lower(TG_OP) END); RETURN NEW; END $$;
CREATE TRIGGER audit_patients AFTER INSERT OR UPDATE ON public.patients FOR EACH ROW EXECUTE FUNCTION public.log_fax_change();
CREATE TRIGGER audit_documents AFTER INSERT OR UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.log_fax_change();
CREATE TRIGGER audit_attempts AFTER INSERT ON public.fax_attempts FOR EACH ROW EXECUTE FUNCTION public.log_fax_change();
CREATE TRIGGER audit_files AFTER INSERT ON public.document_files FOR EACH ROW EXECUTE FUNCTION public.log_fax_change();
CREATE INDEX documents_patient_idx ON public.documents(patient_id); CREATE INDEX attempts_document_idx ON public.fax_attempts(document_id); CREATE INDEX files_document_idx ON public.document_files(document_id);
INSERT INTO public.patients(first_name,last_name,patient_id,date_of_birth,phone,insurance,referring_physician,referring_physician_fax,is_demo) VALUES ('John','Smith','DEMO-001','1958-01-15','(347) 555-0101','Medicare','Dr. Williams','(718) 555-0100',true),('Maria','Santos','DEMO-002','1964-04-03','(347) 555-0102','Aetna','Dr. Patel','(718) 555-0102',true),('Robert','Johnson','DEMO-003','1972-08-19','(347) 555-0103','Medicare','Dr. Chen','(718) 555-0103',true),('Sarah','Williams','DEMO-004','1980-12-11','(347) 555-0104','Healthfirst','Dr. Lee','(718) 555-0104',true),('Michael','Brown','DEMO-005','1956-06-22','(347) 555-0105','Medicare','Dr. Rivera','(718) 555-0105',true),('Angela','Rivera','DEMO-006','1969-02-27','(347) 555-0106','EmblemHealth','Dr. Jones','(718) 555-0106',true),('David','Kim','DEMO-007','1978-10-09','(347) 555-0107','UnitedHealthcare','Dr. Singh','(718) 555-0107',true),('Linda','Chen','DEMO-008','1952-03-14','(347) 555-0108','Medicare','Dr. Patel','(718) 555-0108',true),('James','Wilson','DEMO-009','1984-09-02','(347) 555-0109','Cigna','Dr. Lopez','(718) 555-0109',true),('Patricia','Davis','DEMO-010','1961-07-30','(347) 555-0110','Medicare','Dr. Williams','(718) 555-0110',true);
INSERT INTO public.documents(patient_id,document_type,document_number,document_date,recipient_type,recipient_name,recipient_fax,status,received,received_date,received_document_type,uploaded,uploaded_date,is_demo,created_at) SELECT p.id, CASE n WHEN 1 THEN 'Initial Evaluation' WHEN 2 THEN 'Progress Note' ELSE 'Authorization Packet' END, CASE n WHEN 1 THEN 1 WHEN 2 THEN (row_number() OVER (PARTITION BY n ORDER BY p.patient_id)::integer % 3)+1 ELSE NULL END, CURRENT_DATE - (25-n*4), CASE WHEN n=3 THEN 'Insurance' ELSE 'Referring MD' END, CASE WHEN n=3 THEN p.insurance ELSE p.referring_physician END, p.referring_physician_fax, CASE WHEN n=1 THEN 'Uploaded' WHEN n=2 THEN 'Awaiting Response' ELSE 'Awaiting Upload' END, n<>2, CASE WHEN n<>2 THEN now() - interval '3 days' ELSE NULL END, CASE WHEN n=1 THEN 'Signed Initial Evaluation' WHEN n=3 THEN 'Approved Authorization' ELSE NULL END, n=1, CASE WHEN n=1 THEN now()-interval '2 days' ELSE NULL END, true, now()-interval '10 days' FROM public.patients p CROSS JOIN generate_series(1,3) n WHERE p.is_demo;
INSERT INTO public.fax_attempts(document_id,attempt_number,attempted_at,status,failure_reason,is_demo) SELECT d.id,1,now()-interval '8 days',CASE WHEN d.document_type='Progress Note' THEN 'Failed' ELSE 'Sent Successfully' END, CASE WHEN d.document_type='Progress Note' THEN 'Busy' END,true FROM public.documents d WHERE d.is_demo;
INSERT INTO public.fax_attempts(document_id,attempt_number,attempted_at,status,is_demo) SELECT d.id,2,now()-interval '7 days','Sent Successfully',true FROM public.documents d WHERE d.is_demo AND d.document_type='Progress Note';